package com.oibsip.onlineexam.service;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import com.oibsip.onlineexam.repository.*;import com.oibsip.onlineexam.model.*;import java.util.*;
class ServicesTest { @Test void loginSuccess(){assertNotNull(new AuthenticationService(new UserRepository()).authenticate("student","student123"));} @Test void loginFailure(){assertNull(new AuthenticationService(new UserRepository()).authenticate("student","bad"));} @Test void emptyCredentials(){assertNull(new AuthenticationService(new UserRepository()).authenticate("",""));} @Test void passwordMismatch(){assertThrows(IllegalArgumentException.class,()->new ProfileService().update(new User("u","h","n"),"New","a","b"));} @Test void scoreAndUnanswered(){Question q=new Question(1,"q","a","b","c","d",'B',"");ExamSession s=new ExamSession(List.of(q));s.answer(1,'B');ExamResult r=new ExamService().submit(s,false);assertEquals(1,r.score());assertEquals(100,r.percentage());assertEquals(0,r.unanswered());} @Test void unanswered(){Question q=new Question(1,"q","a","b","c","d",'B',"");ExamSession s=new ExamSession(List.of(q));ExamResult r=new ExamService().submit(s,false);assertEquals(1,r.unanswered());assertEquals(0,r.percentage());} @Test void duplicateSubmission(){ExamSession s=new ExamSession(List.of());s.submit(false);assertTrue(s.isSubmitted());s.submit(true);assertFalse(s.isAutomatic());} @Test void remainingTimeNonNegative(){ExamSession s=new ExamSession(List.of());assertTrue(new ExamService().remainingSeconds(s,0)>=0);} }
